import AppKit

/// The factory images of the four display keys, as Base Camp ships them
/// (`images/default-profile/2_dlogo.png`, `4_explorer.png`, `6_sleep.png`,
/// `3_electic.png`): flat #0044FF background, pure white glyph. The keyboard
/// holds the same pictures in its own flash and restores them on
/// "reset"; these copies let the app show them.
enum FactoryIcons {
    /// D1 — logo Mountain (Base Camp)
    private static let d1 = ""
    /// D2 — explorateur de fichiers
    private static let d2 = ""
    /// D3 — mise en veille
    private static let d3 = ""
    /// D4 — gestionnaire des tâches
    private static let d4 = ""

    private static let cache: [NSImage?] = [d1, d2, d3, d4].map { b64 in
        Data(base64Encoded: b64).flatMap { NSImage(data: $0) }
    }

    /// Factory image of a display key (0 = D1 … 3 = D4).
    static func image(_ key: Int) -> NSImage? {
        (0..<4).contains(key) ? cache[key] : nil
    }

    /// The factory blue — the flat background every default icon uses.
    static let blue: UInt32 = 0x0044FF
}
